84		} else {
85			var invalid *ErrChunkInvalid
86			if !errors.As(err, &invalid) {
87				t.Fatalf("out-of-range = %v, want ErrChunkInvalid", err)
88			}
89		}
90		if _, err := s.PutChunk("dev-1", "att-1", 0, []byte("hell!")); err == nil {
91			t.Fatal("wrong-length non-final chunk accepted")
92		}
93		if _, err := s.PutChunk("dev-1", "att-1", 2, []byte("rld!")); err == nil {
94			t.Fatal("oversized final chunk accepted")
95		}
96		// Ownership is enforced on chunks.
97		if _, err := s.PutChunk("dev-2", "att-1", 0, []byte("hell")); !errors.Is(err, ErrAttachmentForbidden) {
98			t.Fatalf("non-creator chunk = %v, want ErrAttachmentForbidden", err)
99		}
100		if _, err := s.PutChunk("dev-1", "nope", 0, []byte("hell")); !errors.Is(err, ErrAttachmentNotFound) {
101			t.Fatalf("unknown attachment chunk = %v, want ErrAttachmentNotFound", err)
102		}
103	
104		// Finishing before all chunks arrive is incomplete and stays resumable.
105		if _, err := s.CompleteAttachment("dev-1", "att-1"); !errors.Is(err, ErrAttachmentIncomplete) {
106			t.Fatalf("incomplete finish = %v, want ErrAttachmentIncomplete", err)
107		}
108		if _, err := s.CompleteAttachment("dev-2", "att-1"); !errors.Is(err, ErrAttachmentForbidden) {
109			t.Fatalf("non-creator finish = %v, want ErrAttachmentForbidden", err)
110		}
111	
112		if _, err := s.PutChunk("dev-1", "att-1", 0, []byte("hell")); err != nil {
113			t.Fatal(err)
114		}
115		if _, err := s.PutChunk("dev-1", "att-1", 2, []byte("rld")); err != nil {
116			t.Fatal(err)
117		}
118		res, err := s.CompleteAttachment("dev-1", "att-1")
119		if err != nil {
120			t.Fatalf("complete: %v", err)
121		}
122		if res.ID != "att-1" || res.Size != 11 || res.SHA256 != digestOf(content) || !res.Complete || res.Reused {
123			t.Fatalf("complete result = %+v", res)
124		}
125		// A repeat finish returns the same recorded result.
126		res2, err := s.CompleteAttachment("dev-1", "att-1")
127		if err != nil || res2 != res {
128			t.Fatalf("repeat complete = %+v %v, want %+v", res2, err, res)
129		}
130	
131		// Metadata readback: indices and completion status.
132		a, indices, err := s.GetAttachment("dev-1", "att-1")
133		if err != nil {
134			t.Fatal(err)
135		}
136		if !a.Complete || len(indices) != 3 || indices[0] != 0 || indices[2] != 2 {
137			t.Fatalf("get attachment = %+v %v", a, indices)
138		}
139		if _, _, err := s.GetAttachment("dev-2", "att-1"); !errors.Is(err, ErrAttachmentForbidden) {
140			t.Fatalf("non-creator read = %v, want ErrAttachmentForbidden", err)
141		}
142	
143		// Chunk readback and misses.
144		data, err := s.GetAttachmentChunk("dev-1", "att-1", 2)
145		if err != nil || string(data) != "rld" {
146			t.Fatalf("get chunk = %q %v", data, err)
147		}
148		// An out-of-range index is an invalid request (HTTP 400), not a missing
149		// chunk; an in-range index with no chunk is a not-found.
150		var invalid *ErrChunkInvalid
151		if _, err := s.GetAttachmentChunk("dev-1", "att-1", 5); !errors.As(err, &invalid) {
152			t.Fatalf("out-of-range chunk = %v, want *ErrChunkInvalid", err)
153		}
154	}
