305		h, s = open(t)
306		defer func() { _ = s.Close() }()
307		if w := getChunk(t, h, "dev-2", "att-1", 0); w.Code != http.StatusForbidden {
308			t.Fatalf("revoked chunk after restart = %d, want 403", w.Code)
309		}
310		w, body = setAccess(t, h, "dev-1", "att-1", "dev-2", "revoke")
311		if w.Code != http.StatusOK || body["changed"] != false {
312			t.Fatalf("revoke retry after restart = %d %v", w.Code, body)
313		}
314	}
315	
316	// Concurrent grant/revoke calls on one attachment each commit completely:
317	// every call answers 200 and the final state is one of the two committed
318	// states, never a torn one.
319	func TestAttachmentAccessConcurrentGrantRevoke(t *testing.T) {
