416		w, body := doRequest(t, h, http.MethodGet, "/v1/sessions/ghost/documents/doc/changes?limit=0")
417		if w.Code != http.StatusBadRequest || body["error"] == nil {
418			t.Fatalf("bad param + missing session = %d %v", w.Code, body)
419		}
420	}
421	
422	func TestDeviceSessionEmptyIDsReturnJSON400(t *testing.T) {
423		h, _ := newTestHandler(t)
424		registerDevice(t, h, "dev")
425		w, _ := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "sess"})
426		if w.Code != http.StatusOK {
427			t.Fatal(w.Body.String())
428		}
429	
430		paths := []struct {
431			method string
432			path   string
433		}{
434			{http.MethodPost, "/v1/devices//sessions"},
435			{http.MethodDelete, "/v1/devices//sessions/sess"},
436			{http.MethodDelete, "/v1/devices/dev/sessions/"},
437			{http.MethodDelete, "/v1/devices/dev/sessions//"},
438			{http.MethodGet, "/v1/sessions//documents/doc/changes"},
439			{http.MethodGet, "/v1/sessions/sess/documents//changes"},
440			{http.MethodGet, "/v1/sessions/sess/documents/doc/changes/"},
441		}
442		for _, tc := range paths {
443			r := newJSONRequest(tc.method, tc.path, `{"deviceId":"d"}`, "application/json")
444			w := serveRecorder(h, r)
445			if w.Code != http.StatusBadRequest {
446				t.Fatalf("%s %s = %d, want 400", tc.method, tc.path, w.Code)
447			}
448			assertJSONError(t, w)
449		}
450	}
451	
452	func TestDeviceSessionHTTPRestartPersists(t *testing.T) {
453		path := filepath.Join(t.TempDir(), "sync.db")
454	
455		s, err := app.Open(path)
456		if err != nil {
457			t.Fatal(err)
458		}
459		h := NewHandler(s)
460		registerDevice(t, h, "dev-1")
461		w, _ := postJSON(t, h, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
462		if w.Code != http.StatusOK {
463			t.Fatal(w.Body.String())
464		}
465		if err := s.Close(); err != nil {
466			t.Fatal(err)
467		}
468	
469		s2, err := app.Open(path)
470		if err != nil {
471			t.Fatal(err)
472		}
473		t.Cleanup(func() { _ = s2.Close() })
474		h2 := NewHandler(s2)
475	
476		// Replay is idempotent and the session-scoped read still works.
477		w, body := postJSON(t, h2, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
478		if w.Code != http.StatusOK || body["created"] != false {
479			t.Fatalf("session replay = %d %v", w.Code, body)
480		}
481		w, _ = doRequest(t, h2, http.MethodGet, "/v1/sessions/sess/documents/doc/changes")
482		if w.Code != http.StatusOK {
483			t.Fatalf("session read after restart = %d %s", w.Code, w.Body.String())
484		}
485	
486		// Delete persists across the next restart.
487		w, _ = doRequest(t, h2, http.MethodDelete, "/v1/devices/dev-1/sessions/sess")
488		if w.Code != http.StatusOK {
489			t.Fatal(w.Body.String())
490		}
491		if err := s2.Close(); err != nil {
492			t.Fatal(err)
493		}
494		s3, err := app.Open(path)
495		if err != nil {
496			t.Fatal(err)
497		}
498		t.Cleanup(func() { _ = s3.Close() })
499		h3 := NewHandler(s3)
500		w, _ = doRequest(t, h3, http.MethodGet, "/v1/sessions/sess/documents/doc/changes")
501		if w.Code != http.StatusNotFound {
502			t.Fatalf("deleted session after restart = %d, want 404", w.Code)
503		}
504		w, body = postJSON(t, h3, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
505		if w.Code != http.StatusOK || body["created"] != true {
506			t.Fatalf("recreate after restart = %d %v", w.Code, body)
507		}
508	}
509	
510	func TestConcurrentSessionLifecycleHTTP(t *testing.T) {
511		h, _ := newTestHandler(t)
512		registerDevice(t, h, "dev")
513	
514		// Concurrent identical creates: exactly one creator.
515		const n = 40
516		var wg sync.WaitGroup
517		var mu sync.Mutex
518		creators := 0
519		errs := make(chan error, n)
520		for i := 0; i < n; i++ {
521			wg.Add(1)
522			go func() {
523				defer wg.Done()
524				w, body := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
525				if w.Code != http.StatusOK {
526					errs <- fmt.Errorf("status %d: %s", w.Code, w.Body.String())
527					return
528				}
529				if body["created"] == true {
530					mu.Lock()
531					creators++
532					mu.Unlock()
533				}
534			}()
535		}
536		wg.Wait()
537		close(errs)
538		for err := range errs {
539			t.Fatal(err)
540		}
541		if creators != 1 {
542			t.Fatalf("creators = %d, want 1", creators)
543		}
544	
545		// Concurrent delete vs. create: in the end exactly one of {live, absent}
546		// holds consistently, and the next state is coherent (repeat delete 404s
547		// iff the delete won; create reports created=true iff it ran after removal).
548		var wg2 sync.WaitGroup
549		statuses := make(chan int, 2)
550		wg2.Add(2)
551		go func() {
552			defer wg2.Done()
553			w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
554			statuses <- w.Code
555		}()
556		go func() {
557			defer wg2.Done()
558			w, _ := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
559			statuses <- w.Code
560		}()
561		wg2.Wait()
562		close(statuses)
563		for code := range statuses {
564			if code != http.StatusOK {
565				t.Fatalf("racing delete/create status = %d", code)
566			}
567		}
568	
569		// The race settles into exactly one coherent state (live or absent). A
570		// final owner delete then forces "absent": 200 if it was live, 404 if the
571		// racing delete already won. Afterwards both the read and a repeat delete
572		// must observe the same absent state — no half-deleted or duplicated row.
573		w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
574		if w.Code != http.StatusOK && w.Code != http.StatusNotFound {
575			t.Fatalf("settling delete = %d", w.Code)
576		}
577		w, _ = doRequest(t, h, http.MethodGet, "/v1/sessions/hot/documents/d/changes")
578		if w.Code != http.StatusNotFound {
579			t.Fatalf("session should be absent after settle, GET = %d", w.Code)
580		}
581		w, _ = doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
582		if w.Code != http.StatusNotFound {
583			t.Fatalf("repeat delete after settle = %d, want 404", w.Code)
584		}
585	}
